import os
import openai

def moderate_batch(payload, config=None):
    config = config or {}
    client = openai.OpenAI(api_key=config.get('api_key', os.getenv('OPENAI_API_KEY')))
    results = []
    for message in payload:
        response = client.moderations.create(input=message)
        results.append({
            'flagged': response.results[0].flagged,
            'categories': response.results[0].categories.to_dict()
        })
    return results
